 Mode current;Keyboard keyboard;Gamepad pad;InputSettings.BackgroundBehavior background;string folder;int errors;bool restored;readonly StringBuilder log=new StringBuilder();readonly Dictionary<string,string> saved=new Dictionary<string,string>();readonly HashSet<string> absent=new HashSet<string>();
