 IEnumerator Load(int index){current?.stop();current=null;SportsFocusProbe.InjectFocus(true);InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;Time.timeScale=1;switch(index){
