 case 1:yield return SportsProbeScene.Ensure<BowlingMatch>("TruckBowling");var b=FindAnyObjectByType<BowlingMatch>();current=new Mode{key=BowlingMatch.SetupKey,configure=n=>{b.setup.count=1;b.setup.mode=BowlingMode.Simultaneous;Config(b.setup,n);},start=b.StartMatch,stop=b.ChangeSetup,resume=b.Resume,screen=()=>b.menus.Screen.ToString(),released=()=>b.setup.players[0].released,body=()=>b.lanes[0].truck.body,assign=g=>b.Assign(0,g)};break;
 case 2:yield return SportsProbeScene.Ensure<CornholeMatch>("TruckCornhole");var c=FindAnyObjectByType<CornholeMatch>();current=new Mode{key=CornholeMatch.SetupKey,configure=n=>{c.setup.count=1;Config(c.setup,n);},start=c.StartMatch,stop=c.ChangeSetup,resume=c.Resume,screen=()=>c.menus.Screen.ToString(),released=()=>c.setup.players[0].released,body=()=>c.courses[0].Current.body,assign=g=>c.Assign(0,g)};break;
 case 3:yield return SportsProbeScene.Ensure<HockeyMatch>("TruckHockey");var h=FindAnyObjectByType<HockeyMatch>();current=new Mode{key=HockeyMatch.SetupKey,configure=n=>{h.mode=HockeyMode.Custom;Config(h.players,n);},start=()=>h.StartMatch(),stop=h.ChangeSetup,resume=h.Resume,screen=()=>h.menus.Screen.ToString(),released=()=>h.players[0].released,body=()=>h.trucks[0].body,assign=g=>h.Assign(0,g)};break;
