 case 5:yield return SportsProbeScene.Ensure<WallballMatch>("TruckWallball");var w=FindAnyObjectByType<WallballMatch>();current=new Mode{key=WallballMatch.SetupKey,configure=n=>{w.mode=WallballMode.Custom;w.blueSize=w.orangeSize=1;Config(w.players,n);w.jumpKeys[0]=Key.Space;},start=()=>w.StartMatch(),stop=w.ChangeSetup,resume=w.Resume,screen=()=>w.menus.Screen.ToString(),released=()=>w.players[0].released,body=()=>w.trucks[0].body,assign=g=>w.Assign(0,g)};break;
 case 6:yield return SportsProbeScene.Ensure<CheeseMatch>("TruckCheeseRolling");var cheese=FindAnyObjectByType<CheeseMatch>();current=new Mode{key=CheeseMatch.SetupKey,configure=n=>{cheese.setup.count=1;Config(cheese.setup,n);},start=cheese.StartMatch,stop=cheese.ChangeSetup,resume=cheese.Resume,screen=()=>cheese.menus.Screen.ToString(),released=()=>cheese.setup.players[0].released,body=()=>cheese.trucks[0].body,assign=g=>cheese.Assign(0,g)};break;
 default:yield return SportsProbeScene.Ensure<BilliardsSession>("TruckBilliards");var s=FindAnyObjectByType<BilliardsSession>();current=new Mode{key=BilliardsSession.SetupKey,configure=n=>{s.mode=BilliardsMode.Custom;foreach(var player in s.players){player.control=BilliardsControl.AI;player.pad=null;}if(n!=1){s.players[0].control=n==2?BilliardsControl.Gamepad:BilliardsControl.KeyboardWASD;s.players[0].pad=n==2?pad:null;}},start=s.StartMatch,stop=()=>{s.Show(BilliardsScreen.Setup);},resume=s.Resume,screen=()=>s.Screen.ToString(),released=()=>s.players[0].released,body=()=>s.match.balls[0].body,assign=g=>s.Assign(0,g)};break;}
 yield return null;Save(current.key);Check(FindObjectsByType<SportsFocusPolicy>().Length==1,"family="+index+" exactly one active scene focus policy");}
 bool Playing=>current.screen()=="Play"||current.screen()=="Match";
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("FocusMatrixEvidence");background=InputSystem.settings.backgroundBehavior;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;keyboard=InputSystem.AddDevice<Keyboard>();InputSystem.EnableDevice(keyboard);pad=InputSystem.AddDevice<Gamepad>();Application.logMessageReceived+=Error;
 for(int family=0;family<8;family++){yield return Load(family);for(int source=0;source<3;source++){current.stop();current.configure(source);InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.QueueStateEvent(pad,new GamepadState());yield return null;Check(current.start(),"family="+family+" source="+source+" starts");yield return new WaitForSeconds(source!=1&&(family==3||family==4)?3.3f:.2f);InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.ResetAndDisableAllDevices;SportsFocusProbe.InjectFocus(false);yield return null;yield return null;
 if(source==1){float clock=Time.time;yield return new WaitForSecondsRealtime(.15f);Check(Playing&&Time.timeScale>0&&Time.time>clock+.05f,"family="+family+" all-AI remains autonomous while all attached devices focus-suspended");}else{Check(current.screen()=="Pause"&&Time.timeScale==0,"family="+family+" source="+source+" ordinary focus pause instead of reconnect");var body=current.body();var pos=body.position;var velocity=body.linearVelocity;yield return new WaitForSecondsRealtime(.12f);Check(body.position==pos&&body.linearVelocity==velocity,"family="+family+" source="+source+" exact paused body motion preserved");}
 SportsFocusProbe.InjectFocus(true);InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;yield return null;if(source!=1){Check(current.screen()=="Pause","family="+family+" focus return never auto-resumes");if(source==0)InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.W));else InputSystem.QueueStateEvent(pad,new GamepadState{rightTrigger=1});yield return null;current.resume();yield return null;yield return null;Check(Playing&&!current.released(),"family="+family+" source="+source+" held input cannot leak through resume");InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.QueueStateEvent(pad,new GamepadState());yield return null;yield return null;Check(current.released(),"family="+family+" source="+source+" neutral arms normal play");}
 if(source==0){InputSystem.RemoveDevice(keyboard);keyboard=null;yield return null;yield return null;Check((current.screen()=="Join"||current.screen()=="Disconnect")&&Time.timeScale==0,"family="+family+" actual software keyboard removal still opens reconnect");keyboard=InputSystem.AddDevice<Keyboard>();InputSystem.EnableDevice(keyboard);InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return null;current.resume();yield return null;Check(Playing,"family="+family+" same keyboard assignment resumes with replacement keyboard");}
 if(source==2){InputSystem.RemoveDevice(pad);pad=null;yield return null;yield return null;Check((current.screen()=="Join"||current.screen()=="Disconnect")&&Time.timeScale==0,"family="+family+" real software controller removal still requires reconnect");pad=InputSystem.AddDevice<Gamepad>();Check(current.assign(pad),"family="+family+" explicit replacement source accepted");InputSystem.QueueStateEvent(pad,new GamepadState());yield return null;current.resume();yield return null;Check(Playing,"family="+family+" replacement resumes existing match");}
 current.stop();}
 }
 Restore();log.AppendLine("ERRORS="+errors+". Eight saved-scene families, actual InputSystem focus disable/sync with injected devices and real software removal/replacement. No physical controllers, human playtesting or OS focus claim.");File.WriteAllText(folder+"/result.txt",log.ToString());if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Error;SportsFocusProbe.InjectFocus(true);current?.stop();current=null;foreach(var pair in saved)SportsPrefs.SetString(pair.Key,pair.Value);foreach(var key in absent)SportsPrefs.DeleteKey(key);SportsPrefs.Save();InputSystem.settings.backgroundBehavior=background;if(pad!=null&&pad.added)InputSystem.RemoveDevice(pad);if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);Time.timeScale=1;}void OnDestroy(){Restore();}
